const NAMES=['Ana','Pedro','Lia','Caio','Bia','Téo','Maria','João','Luna','Davi','Júlia','Rafa'];
const UNITS=[];
const G=10;
const E10=e=>String(e).replace('-','−');
const SCI=(m,e)=>`${fmt(m)} × 10<sup>${E10(e)}</sup>`;
function sciNorm(v){ if(v===0)return [0,0]; let e=Math.floor(Math.log10(Math.abs(v))); let m=round(v/10**e,3); if(Math.abs(m)>=10){m=round(m/10,3);e++;} return [m,e]; }
const SCIV=v=>{const [m,e]=sciNorm(v);return SCI(m,e);};

/* ---------- Ilustrações de física ---------- */
function vtSVG(v0,v1,t,yl){ const ox=46,oy=160,sx=200/t,mx=Math.max(v0,v1,1),sy=120/mx; const X=s=>(ox+s*sx).toFixed(1),Y=v=>(oy-v*sy).toFixed(1);
  return SV(290,195,`<polygon points="${X(0)},${oy} ${X(0)},${Y(v0)} ${X(t)},${Y(v1)} ${X(t)},${oy}" fill="#ddf4ff"/>
  <line x1="${ox}" y1="${oy}" x2="270" y2="${oy}" stroke="#777" stroke-width="2"/><line x1="${ox}" y1="${oy}" x2="${ox}" y2="15" stroke="#777" stroke-width="2"/>
  <line x1="${X(0)}" y1="${Y(v0)}" x2="${X(t)}" y2="${Y(v1)}" stroke="#1899d6" stroke-width="4" stroke-linecap="round"/>
  <line x1="${X(t)}" y1="${Y(v1)}" x2="${X(t)}" y2="${oy}" stroke="#1899d6" stroke-width="2" stroke-dasharray="5 4"/><line x1="${ox}" y1="${Y(v1)}" x2="${X(t)}" y2="${Y(v1)}" stroke="#1899d6" stroke-width="2" stroke-dasharray="5 4"/>
  <text x="${ox-6}" y="${+Y(v0)+5}" text-anchor="end" fill="#1899d6" font-size="14">${v0}</text><text x="${ox-6}" y="${+Y(v1)+5}" text-anchor="end" fill="#1899d6" font-size="14">${v1}</text>
  <text x="${X(t)}" y="${oy+18}" text-anchor="middle" fill="#1899d6" font-size="14">${t}</text><text x="${ox-6}" y="${oy+18}" text-anchor="end" fill="#777" font-size="13">0</text>
  <text x="${ox+4}" y="14" fill="#777" font-size="13">${yl||'v (m/s)'}</text><text x="272" y="${oy-6}" text-anchor="end" fill="#777" font-size="13">t (s)</text>`); }
function blockSVG(fr,fl,lbl){ return SV(300,120,`<line x1="10" y1="92" x2="290" y2="92" stroke="#777" stroke-width="3"/><rect x="115" y="42" width="70" height="50" rx="6" fill="#fff4d6" stroke="#ff9600" stroke-width="3"/><text x="150" y="73" text-anchor="middle" fill="#e07b00" font-size="15">${lbl||''}</text>
  ${fr?`<line x1="185" y1="67" x2="270" y2="67" stroke="#58a700" stroke-width="4"/><polygon points="270,59 286,67 270,75" fill="#58a700"/><text x="232" y="56" text-anchor="middle" fill="#58a700" font-size="15">${fr}</text>`:''}
  ${fl?`<line x1="115" y1="67" x2="30" y2="67" stroke="#ea2b2b" stroke-width="4"/><polygon points="30,59 14,67 30,75" fill="#ea2b2b"/><text x="68" y="56" text-anchor="middle" fill="#ea2b2b" font-size="15">${fl}</text>`:''}`); }
function inclineSVG(ang,lbl){ return SV(290,170,`<polygon points="20,150 270,150 270,40" fill="#f3e3ff" stroke="#a568cc" stroke-width="3" stroke-linejoin="round"/><g transform="translate(150,97) rotate(-23.7)"><rect x="-22" y="-34" width="44" height="32" rx="4" fill="#fff4d6" stroke="#ff9600" stroke-width="3"/></g><path d="M70,150 A50,50 0 0 0 66,130" fill="none" stroke="#a568cc" stroke-width="3"/><text x="78" y="143" fill="#a568cc" font-size="15">${ang}</text>${lbl?`<text x="200" y="168" text-anchor="middle" fill="#a568cc" font-size="14">${lbl}</text>`:''}`); }
function waveSVG(n,lbl){ let d='M20,70'; const W=250/n; for(let i=0;i<n;i++){ const x=20+i*W; d+=` Q${(x+W/4).toFixed(1)},10 ${(x+W/2).toFixed(1)},70 Q${(x+3*W/4).toFixed(1)},130 ${(x+W).toFixed(1)},70`; }
  return SV(290,170,`<line x1="15" y1="70" x2="280" y2="70" stroke="#ccc" stroke-width="2" stroke-dasharray="4 4"/><path d="${d}" fill="none" stroke="#1cb0f6" stroke-width="4"/><line x1="20" y1="150" x2="270" y2="150" stroke="#e07b00" stroke-width="2"/><line x1="20" y1="142" x2="20" y2="158" stroke="#e07b00" stroke-width="2"/><line x1="270" y1="142" x2="270" y2="158" stroke="#e07b00" stroke-width="2"/><text x="145" y="144" text-anchor="middle" fill="#e07b00" font-size="15">${lbl}</text>`); }
function circuitSVG(rs,parallel,U){ const bat=(x,y)=>`<rect x="${x-10}" y="${y-16}" width="20" height="32" style="fill:var(--bg)"/><line x1="${x-7}" y1="${y-16}" x2="${x-7}" y2="${y+16}" stroke="#3c3c3c" stroke-width="3"/><line x1="${x+5}" y1="${y-8}" x2="${x+5}" y2="${y+8}" stroke="#3c3c3c" stroke-width="5"/>${U?`<text x="${x+16}" y="${y+5}" fill="#3c3c3c" font-size="14">${U}</text>`:''}`;
  if(!parallel){ let g=`<rect x="30" y="30" width="250" height="110" fill="none" stroke="#777" stroke-width="3" rx="6"/>`+bat(30,85); const n=rs.length; rs.forEach((r,i)=>{ const cx=80+(i+.5)*(190/n); g+=`<rect x="${cx-22}" y="21" width="44" height="18" rx="3" fill="#fff4d6" stroke="#ff9600" stroke-width="3"/><text x="${cx}" y="15" text-anchor="middle" fill="#e07b00" font-size="14">${r}</text>`; }); return SV(300,150,g); }
  const n=rs.length,xs=rs.map((_,i)=>120+i*(150/Math.max(1,n-1||1))); const xl=xs[xs.length-1];
  let g=`<path d="M30,30 H${xl} M30,170 H${xl} M30,30 V170" fill="none" stroke="#777" stroke-width="3"/>`+bat(30,100);
  xs.forEach((x,i)=>{ g+=`<line x1="${x}" y1="30" x2="${x}" y2="170" stroke="#777" stroke-width="3"/><rect x="${x-9}" y="78" width="18" height="44" rx="3" fill="#fff4d6" stroke="#ff9600" stroke-width="3"/><text x="${x+14}" y="105" fill="#e07b00" font-size="14">${rs[i]}</text>`; });
  return SV(Math.max(300,xl+60),190,g); }

/* ------------------------ UNIDADE 1 — FUNDAMENTOS ------------------------ */
const SIU=[['comprimento','metro (m)'],['massa','quilograma (kg)'],['tempo','segundo (s)'],['força','newton (N)'],['energia','joule (J)'],['potência','watt (W)'],['temperatura absoluta','kelvin (K)'],['corrente elétrica','ampère (A)'],['pressão','pascal (Pa)'],['carga elétrica','coulomb (C)'],['frequência','hertz (Hz)'],['resistência elétrica','ohm (Ω)'],['tensão elétrica','volt (V)']];
UNITS.push({id:'f1',title:'Fundamentos da Física',sub:'9º ano · grandezas, unidades, conversões e vetores',color:'#58cc02',dark:'#58a700',skills:[
{id:'grand',name:'Grandezas e unidades',icon:'📏',tip:'No SI: comprimento em metro, massa em quilograma, tempo em segundo. Grandezas vetoriais precisam de módulo, direção e sentido.',
theory:`<p><b>Grandeza física</b> é tudo o que pode ser medido. O <b>Sistema Internacional (SI)</b> padroniza as unidades.</p>
<table><tr><th>Grandeza</th><th>Unidade SI</th></tr><tr><td>Comprimento</td><td>metro (m)</td></tr><tr><td>Massa</td><td>quilograma (kg)</td></tr><tr><td>Tempo</td><td>segundo (s)</td></tr><tr><td>Força</td><td>newton (N)</td></tr><tr><td>Energia / trabalho</td><td>joule (J)</td></tr><tr><td>Potência</td><td>watt (W)</td></tr><tr><td>Pressão</td><td>pascal (Pa)</td></tr><tr><td>Temperatura</td><td>kelvin (K)</td></tr><tr><td>Corrente elétrica</td><td>ampère (A)</td></tr></table>
<h3>Escalares × vetoriais</h3><ul><li><b>Escalares</b>: bastam número e unidade (massa, tempo, energia, temperatura).</li><li><b>Vetoriais</b>: precisam de módulo, direção e sentido (velocidade, aceleração, força, deslocamento).</li></ul>
<h3>Prefixos</h3><p>giga (G) = 10<sup>9</sup> · mega (M) = 10<sup>6</sup> · quilo (k) = 10<sup>3</sup> · centi (c) = 10<sup>−2</sup> · mili (m) = 10<sup>−3</sup> · micro (µ) = 10<sup>−6</sup> · nano (n) = 10<sup>−9</sup></p>`,
gens:[
 lv=>{const it=pick(SIU);return MC(`Qual é a unidade de <b>${it[0]}</b> no Sistema Internacional (SI)?`,it[1],shuffle(SIU.filter(x=>x!==it)).map(x=>x[1]),`No SI, ${it[0]} é medida em <b>${it[1]}</b>.`,'Lembre das unidades básicas: m, kg, s, A, K, mol, cd.');},
 lv=>{const it=pick(SIU);return MC(`O <b>${it[1]}</b> é unidade de qual grandeza?`,it[0][0].toUpperCase()+it[0].slice(1),shuffle(SIU.filter(x=>x!==it)).map(x=>x[0][0].toUpperCase()+x[0].slice(1)),`${it[1]} mede ${it[0]}.`,'Associe cada unidade à sua grandeza.');},
 lv=>{const it=pick([['velocidade','Vetorial'],['massa','Escalar'],['força','Vetorial'],['temperatura','Escalar'],['aceleração','Vetorial'],['energia','Escalar'],['tempo','Escalar'],['deslocamento','Vetorial'],['impulso','Vetorial'],['volume','Escalar'],['peso','Vetorial'],['potência','Escalar']]);return MC(`A grandeza <b>${it[0]}</b> é:`,it[1],['Escalar','Vetorial'],`${it[0][0].toUpperCase()+it[0].slice(1)} é ${it[1].toLowerCase()}: ${it[1]==='Vetorial'?'precisa de módulo, direção e sentido':'fica definida só por número e unidade'}.`,'Pergunte-se: importa para onde ela aponta?',{keep:true});},
 lv=>{const P=[['giga (G)',9],['mega (M)',6],['quilo (k)',3],['centi (c)',-2],['mili (m)',-3],['micro (µ)',-6],['nano (n)',-9]];const p=pick(P);return MC(`Qual é o valor do prefixo <b>${p[0]}</b>?`,`10<sup>${E10(p[1])}</sup>`,shuffle(P.filter(x=>x!==p)).map(x=>`10<sup>${E10(x[1])}</sup>`),`${p[0]} = 10<sup>${E10(p[1])}</sup>.`,'Quilo = mil; mili = milésimo; micro = milionésimo.');},
 lv=>{const c=pick([['cm','m',0.01],['mm','m',0.001],['g','kg',0.001],['min','s',60],['h','s',3600],['km','m',1000],['mL','L',0.001],['kg','g',1000],['L','m³',0.001]]);const v=R(1,40)*pick([5,10,25]);return NUM(`Quantos <b>${c[1]}</b> são <b>${nf(v)} ${c[0]}</b>?`,v*c[2],`1 ${c[0]} = ${fmt(c[2])} ${c[1]} → ${nf(v)} × ${fmt(c[2])} = <b>${fmt(v*c[2])} ${c[1]}</b>.`,`Use 1 ${c[0]} = ${fmt(c[2])} ${c[1]}.`,{unit:c[1],keys:[',']});},
]},
{id:'conv',name:'Conversão km/h ↔ m/s',icon:'🚗',tip:'De km/h para m/s: divida por 3,6. De m/s para km/h: multiplique por 3,6.',
theory:`<p>1 km/h = 1000 m / 3600 s = ${F(1,'3,6')} m/s.</p><div class="formula">km/h ÷ 3,6 = m/s · m/s × 3,6 = km/h</div>
<div class="ex">72 km/h ÷ 3,6 = <b>20 m/s</b> · 15 m/s × 3,6 = <b>54 km/h</b></div>
<h3>Valores úteis</h3><p>36 km/h = 10 m/s · 54 km/h = 15 m/s · 72 km/h = 20 m/s · 90 km/h = 25 m/s · 108 km/h = 30 m/s</p>
<p>Nas fórmulas, use unidades coerentes: se a distância está em metros e o tempo em segundos, a velocidade deve estar em m/s.</p>`,
gens:[
 lv=>{const k=R(1,10);return NUM(`Converta <b>${18*k} km/h</b> para m/s.`,5*k,`${18*k} ÷ 3,6 = <b>${5*k} m/s</b>.`,'Divida por 3,6.',{unit:'m/s'});},
 lv=>{const v=R(2,40);return NUM(`Converta <b>${v} m/s</b> para km/h.`,v*3.6,`${v} × 3,6 = <b>${fmt(v*3.6)} km/h</b>.`,'Multiplique por 3,6.',{unit:'km/h',keys:[',']});},
 lv=>{const k=R(2,8),b=pick([5*k-5,5*k,5*k+5]);const a=18*k;const c=b>5*k?`${b} m/s`:b<5*k?`${a} km/h`:'Têm a mesma velocidade';return MC(`Qual é mais rápido: <b>${a} km/h</b> ou <b>${b} m/s</b>?`,c,[`${a} km/h`,`${b} m/s`,'Têm a mesma velocidade'],`${a} km/h = ${5*k} m/s, que comparamos com ${b} m/s.`,'Converta tudo para a mesma unidade.',{keep:true});},
 lv=>{const s=pick([['Para converter km/h em m/s, divide-se por 3,6.',true],['Para converter m/s em km/h, divide-se por 3,6.',false],['36 km/h equivalem a 10 m/s.',true],['1 m/s é mais rápido que 1 km/h.',true],['72 km/h equivalem a 25 m/s.',false],['108 km/h equivalem a 30 m/s.',true]]);return TF(s[0],s[1],'Lembre: km/h ÷ 3,6 = m/s e m/s × 3,6 = km/h. (72 km/h = 20 m/s; 90 km/h = 25 m/s.)','1 m/s = 3,6 km/h.');},
 lv=>{const d=pick([100,200,400]),v=pick([5,8,10]);return NUM(`Um atleta percorre <b>${d} m</b> em <b>${d/v} s</b>. Qual sua velocidade média em <b>km/h</b>?`,v*3.6,`v = ${d} ÷ ${d/v} = ${v} m/s → ${v} × 3,6 = <b>${fmt(v*3.6)} km/h</b>.`,'Calcule em m/s e depois multiplique por 3,6.',{unit:'km/h',keys:[',']});},
]},
{id:'ordem',name:'Notação científica e ordem de grandeza',icon:'🔬',tip:'N = a × 10ⁿ com 1 ≤ a < 10. Ordem de grandeza: se a < 3,16 é 10ⁿ; se a ≥ 3,16 é 10ⁿ⁺¹.',
theory:`<div class="formula">N = a × 10<sup>n</sup> (1 ≤ a < 10)</div><div class="ex">Velocidade da luz: 300 000 000 m/s = 3 × 10<sup>8</sup> m/s · Carga do elétron: 1,6 × 10<sup>−19</sup> C</div>
<h3>Ordem de grandeza (OG)</h3><p>É a potência de 10 mais próxima do número. Compare o coeficiente com √10 ≈ 3,16:</p><ul><li>a < 3,16 → OG = 10<sup>n</sup></li><li>a ≥ 3,16 → OG = 10<sup>n+1</sup></li></ul><div class="ex">6 × 10<sup>24</sup> kg (massa da Terra) → OG = 10<sup>25</sup></div>
<h3>Operações</h3><p>Multiplicação: multiplica coeficientes e soma expoentes. Divisão: divide coeficientes e subtrai expoentes.</p>`,
gens:[
 lv=>{const mi=R(11,99),e=R(3,9),N=mi*10**(e-1);return MC(`Escreva <b>${nf(N)}</b> em notação científica:`,SCI(mi/10,e),[SCI(mi/10,e-1),SCI(mi/10,e+1),SCI(mi,e),SCI(mi/100,e)],`A vírgula anda ${e} casas para a esquerda: ${SCI(mi/10,e)}.`,'O coeficiente deve ficar entre 1 e 10.');},
 lv=>{const f=pick([['a velocidade da luz (3 × 10<sup>8</sup> m/s)',8],['a massa da Terra (6 × 10<sup>24</sup> kg)',25],['a carga elementar (1,6 × 10<sup>−19</sup> C)',-19],['a distância Terra–Lua (3,8 × 10<sup>8</sup> m)',9],['o raio de um átomo (5 × 10<sup>−11</sup> m)',-10],['a massa do elétron (9,1 × 10<sup>−31</sup> kg)',-30],['a idade do Universo (4,3 × 10<sup>17</sup> s)',18]]);const o=e=>`10<sup>${E10(e)}</sup>`;return MC(`Qual é a <b>ordem de grandeza</b> de ${f[0]}?`,o(f[1]),[o(f[1]-1),o(f[1]+1),o(f[1]+2),o(-f[1])],`Compare o coeficiente com 3,16: ${o(f[1])}.`,'Coeficiente < 3,16 mantém o expoente; ≥ 3,16 soma 1 ao expoente.');},
 lv=>{let a=R(1,4),b=R(1,4);if(a*b>=10)b=1;const m=R(-9,9),n=R(-9,9);return MC(`Quanto é <b>(${SCI(a,m)}) · (${SCI(b,n)})</b>?`,SCI(a*b,m+n),[SCI(a*b,m*n),SCI(a+b,m+n),SCI(a*b,m+n+1),SCI(a*b,m-n)],`Coeficientes: ${a} · ${b} = ${a*b}; expoentes: ${E10(m)} + ${E10(n)} = ${E10(m+n)}.`,'Multiplica coeficientes, soma expoentes.');},
 lv=>{const b=R(1,3),a=R(1,3),m=R(-6,9),n=R(-6,6);return MC(`Quanto é <b>(${SCI(a*b,m)}) ÷ (${SCI(b,n)})</b>?`,SCI(a,m-n),[SCI(a,m+n),SCI(a*b*b,m-n),SCI(a,n-m),SCI(a+1,m-n)],`${a*b} ÷ ${b} = ${a}; expoentes: ${E10(m)} − (${E10(n)}) = ${E10(m-n)}.`,'Divide coeficientes, subtrai expoentes.');},
 lv=>{const mi=R(11,99),k=R(3,7);const dec='0,'+'0'.repeat(k-1)+String(mi);return FILL('Complete o expoente:',`${dec} = ${fmt(mi/10)} × 10<sup>@@</sup>`,-k,`A vírgula anda ${k} casas para a direita: expoente <b>−${k}</b>.`,'Números menores que 1 têm expoente negativo.',{keys:['−']});},
]},
{id:'vet',name:'Vetores',icon:'➡️',tip:'Mesmo sentido: some. Sentidos opostos: subtraia. Perpendiculares: Pitágoras. A resultante fica entre |a − b| e a + b.',
theory:`<p>Um <b>vetor</b> tem módulo (tamanho), direção e sentido.</p>
<h3>Soma de dois vetores</h3><ul><li>Mesmo sentido: R = a + b (máxima)</li><li>Sentidos opostos: R = |a − b| (mínima)</li><li>Perpendiculares: R² = a² + b² (Pitágoras)</li></ul><div class="formula">|a − b| ≤ R ≤ a + b</div>
<div class="ex">Forças de 6 N e 8 N perpendiculares → R = √(36 + 64) = 10 N</div>
<h3>Componentes</h3><div class="formula">F<sub>x</sub> = F · cos θ · F<sub>y</sub> = F · sen θ</div><p>sen 30° = cos 60° = 0,5 · sen 60° = cos 30° ≈ 0,87</p>`,
gens:[
 lv=>{const a=R(2,30),b=R(2,30);return NUM(`Duas forças de <b>${a} N</b> e <b>${b} N</b> atuam na mesma direção e <b>mesmo sentido</b>. Qual é a resultante?`,a+b,`Mesmo sentido: R = ${a} + ${b} = <b>${a+b} N</b>.`,'Vetores no mesmo sentido se somam.',{unit:'N',visual:blockSVG(a+' N + '+b+' N',null)});},
 lv=>{let a=R(2,30),b=R(2,30);if(a===b)b++;return NUM(`Duas forças de <b>${Math.max(a,b)} N</b> (para a direita) e <b>${Math.min(a,b)} N</b> (para a esquerda) atuam num bloco. Qual é o módulo da resultante?`,Math.abs(a-b),`Sentidos opostos: R = ${Math.max(a,b)} − ${Math.min(a,b)} = <b>${Math.abs(a-b)} N</b>, para a direita.`,'Vetores opostos se subtraem.',{unit:'N',visual:blockSVG(Math.max(a,b)+' N',Math.min(a,b)+' N')});},
 lv=>{const [a,b,c]=pick(TRIPLES_F);return NUM(`Duas forças <b>perpendiculares</b> de <b>${a} N</b> e <b>${b} N</b> atuam num corpo. Qual é a resultante?`,c,`R² = ${a}² + ${b}² = ${a*a+b*b} → R = <b>${c} N</b>.`,'Use o Teorema de Pitágoras.',{unit:'N'});},
 lv=>{const a=R(3,12),b=R(3,12),x=a+b+R(1,6);return MC(`Duas forças de <b>${a} N</b> e <b>${b} N</b> atuam num corpo. Qual valor <b>NÃO</b> pode ser o módulo da resultante?`,x+' N',[(a+b)+' N',Math.abs(a-b)+' N',(Math.abs(a-b)+a+b)/2+' N'],`A resultante fica entre |${a} − ${b}| = ${Math.abs(a-b)} N e ${a} + ${b} = ${a+b} N. ${x} N está fora desse intervalo.`,'Calcule a resultante mínima e a máxima.');},
 lv=>{const F=R(2,20)*2,t=Math.random()<.5;return NUM(`Uma força de <b>${F} N</b> forma <b>${t?60:30}°</b> com a horizontal. Qual é sua componente <b>${t?'horizontal':'vertical'}</b>? (use ${t?'cos 60°':'sen 30°'} = 0,5)`,F/2,`${t?'F<sub>x</sub> = F · cos 60°':'F<sub>y</sub> = F · sen 30°'} = ${F} · 0,5 = <b>${F/2} N</b>.`,'Componente horizontal usa cosseno; vertical usa seno (em relação à horizontal).',{unit:'N'});},
 lv=>MC('Para caracterizar completamente uma grandeza vetorial precisamos de:','Módulo, direção e sentido',['Apenas o módulo','Módulo e unidade apenas','Direção e unidade apenas'],'Vetores têm módulo (intensidade), direção (ex.: horizontal) e sentido (ex.: para a direita).','Pense numa seta: tamanho, reta e para onde aponta.'),
]},
]});
